import { Metadata } from 'next';
import { notFound } from 'next/navigation';
import Link from 'next/link';

interface Post {
  id: number;
  title: string;
  body: string;
}

interface Comment {
  id: number;
  name: string;
  body: string;
  email: string;
}

interface PostWithComments {
  post: Post;
  comments: Comment[];
}

interface Params {
  params: Promise<{ id: string }>;
}

export async function generateMetadata({ params }: Metadata): Promise<Metadata> {
  const { id } = await params;
  const postRes = await fetch(`https://jsonplaceholder.typicode.com/posts/${id}`, {
    cache: 'no-store',
  });

  if (!postRes.ok) {
    return {
      title: 'Post Not Found - My Blog',
    };
  }

  const post: Post = await postRes.json();

  return {
    title: `${post.title} - My Blog`,
    description: post.body.substring(0, 160),
    openGraph: {
      title: post.title,
      description: post.body.substring(0, 160),
    },
  };
}

async function getPostWithComments(id: string): Promise<PostWithComments | null> {
  try {
    const [post, comments] = await Promise.all([
      fetch(`https://jsonplaceholder.typicode.com/posts/${id}`, {
        next: { revalidate: 300 },
      }).then((res) => {
        if (!res.ok) return null;
        return res.json() as Promise<Post>;
      }),
      fetch(`https://jsonplaceholder.typicode.com/posts/${id}/comments`, {
        next: { revalidate: 300 },
      }).then((res) => res.json() as Promise<Comment[]>),
    ]);

    if (!post) return null;

    return { post, comments };
  } catch {
    return null;
  }
}

async function getAllPostIds(): Promise<{ id: string }[]> {
  const res = await fetch('https://jsonplaceholder.typicode.com/posts', {
    cache: 'no-store',
  });
  const posts: Post[] = await res.json();

  return posts.slice(0, 10).map((post) => ({
    id: post.id.toString(),
  }));
}

export async function generateStaticParams() {
  return getAllPostIds();
}

export default async function BlogPost({ params }: { params: Promise<{ id: string }> }) {
  const { id } = await params;
  const data = await getPostWithComments(id);

  if (!data) {
    notFound();
  }

  const { post, comments } = data;

  return (
    <article>
      <Link href="/blog">
        <button>← Back</button>
      </Link>

      <h1>{post.title}</h1>
      <p>{post.body}</p>

      <h2>Comments ({comments.length})</h2>
      <div className="comments">
        {comments.map((comment) => (
          <div key={comment.id} className="comment">
            <h3>{comment.name}</h3>
            <p>{comment.body}</p>
            <small>By: {comment.email}</small>
          </div>
        ))}
      </div>
    </article>
  );
}

